using Enset.Domain.GoldProfiles;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace Enset.Infrastructure.Persistence.Configurations;
public sealed class GoldProfileVersionConfiguration:IEntityTypeConfiguration<GoldProfileVersion>{public void Configure(EntityTypeBuilder<GoldProfileVersion>b){b.ToTable("GoldProfileVersions");b.HasKey(x=>x.Id);b.Property(x=>x.EntityType).HasMaxLength(32);b.Property(x=>x.ProfileType).HasMaxLength(64);b.Property(x=>x.SnapshotHash).HasMaxLength(64);b.Property(x=>x.ReleaseStatus).HasConversion<string>().HasMaxLength(24);b.Property(x=>x.RowVersion).IsRowVersion().HasColumnName("xmin");b.HasIndex(x=>new{x.EntityType,x.EntityId,x.VersionNumber}).IsUnique();b.HasIndex(x=>new{x.EntityType,x.EntityId,x.IsCurrent});b.HasIndex(x=>x.ReleaseStatus);b.HasIndex(x=>x.SnapshotHash);}}
public sealed class GoldProfileEventConfiguration:IEntityTypeConfiguration<GoldProfileEvent>{public void Configure(EntityTypeBuilder<GoldProfileEvent>b){b.ToTable("GoldProfileEvents");b.HasKey(x=>x.Id);b.Property(x=>x.EventType).HasMaxLength(32);b.Property(x=>x.PreviousStatus).HasConversion<string>().HasMaxLength(24);b.Property(x=>x.NewStatus).HasConversion<string>().HasMaxLength(24);b.Property(x=>x.SnapshotHash).HasMaxLength(64);b.HasOne(x=>x.Version).WithMany(x=>x.Events).HasForeignKey(x=>x.GoldProfileVersionId);}}
